            int outputOffset = outputBase + i;
            output.set(JAVA_DOUBLE, (long) (outputOffset) * Double.BYTES, left.get(JAVA_DOUBLE, (long) (leftOffset) * Double.BYTES) * right.get(JAVA_DOUBLE, (long) (rightOffset) * Double.BYTES));
