    public static void f64SegmentContiguousVector(Cpu1KernelArgs args, int startInclusive, int endExclusive) {
        Cpu1TensorView leftView = args.input(0);
        Cpu1TensorView rightView = args.input(1);
        Cpu1TensorView outputView = args.output();
        MemorySegment left = leftView.segment();
        MemorySegment right = rightView.segment();
        MemorySegment output = outputView.segment();
        long leftBase = (long) leftView.storageOffset() * Double.BYTES;
        long rightBase = (long) rightView.storageOffset() * Double.BYTES;
        long outputBase = (long) outputView.storageOffset() * Double.BYTES;
        int upper = startInclusive + F64.loopBound(endExclusive - startInclusive);
        int i = startInclusive;
        for (; i < upper; i += F64.length()) {
            long byteIndex = (long) i * Double.BYTES;
            DoubleVector.fromMemorySegment(F64, left, leftBase + byteIndex, ORDER)
                    .mul(DoubleVector.fromMemorySegment(F64, right, rightBase + byteIndex, ORDER))
                    .intoMemorySegment(output, outputBase + byteIndex, ORDER);
        }
        for (; i < endExclusive; i++) {
            long leftOffset = leftBase + (long) i * Double.BYTES;
            long rightOffset = rightBase + (long) i * Double.BYTES;
            long outputOffset = outputBase + (long) i * Double.BYTES;
            output.set(JAVA_DOUBLE, outputOffset, left.get(JAVA_DOUBLE, leftOffset) * right.get(JAVA_DOUBLE, rightOffset));
        }
    }

